"""Factory helpers for resolving email providers."""
from __future__ import annotations

from typing import Any, Dict, Optional

from django.conf import settings
from django.core.exceptions import ImproperlyConfigured
from django.utils.module_loading import import_string


class EmailProviderFactory:
    """Factory for constructing configured email provider instances."""

    @staticmethod
    def create_provider(provider_name: Optional[str] = None, **overrides: Any):
        provider_name = provider_name or getattr(settings, "EMAIL_PROVIDER", "smtp")
        providers_map: Dict[str, str] = getattr(settings, "EMAIL_PROVIDERS", {})

        if provider_name not in providers_map:
            raise ImproperlyConfigured(f"Unknown email provider '{provider_name}'")

        provider_path = providers_map[provider_name]
        provider_class = import_string(provider_path)

        if provider_name == "mailjet":
            config = {**getattr(settings, "MAILJET_CONFIG", {}), **overrides}
            api_key = config.get("API_KEY")
            secret_key = config.get("SECRET_KEY")
            from_email = config.get("FROM_EMAIL", settings.DEFAULT_FROM_EMAIL)

            if not api_key or not secret_key:
                raise ImproperlyConfigured("MAILJET_API_KEY and MAILJET_SECRET_KEY are required for Mailjet provider")

            return provider_class(
                api_key=api_key,
                secret_key=secret_key,
                from_email=from_email,
                from_name=config.get("FROM_NAME"),
                sandbox_mode=config.get("SANDBOX_MODE", settings.DEBUG),
                api_version=config.get("API_VERSION", "v3.1"),
                timeout=config.get("TIMEOUT"),
            )

        return provider_class(**overrides)
